import { Permissions } from '@/enums/permissions.enum';

import { canAccessProposalSearch } from '@/functions/proposal-search-access';
import type { GlobalSearchSectionKey } from '@/lib/command-palette/global-search';

/**
 * Gate FE da Command Palette / histórico unificado.
 * Espelha a união de seções do backend (`CanAccessGlobalSearch`):
 * proposta OU due OU pós.
 */
export function canAccessGlobalSearch(permissions?: readonly string[] | null): boolean {
    return enabledGlobalSearchSections(permissions).length > 0;
}

export function canAccessGlobalSearchPropostas(
    permissions?: readonly string[] | null,
): boolean {
    return canAccessProposalSearch(permissions);
}

export function canAccessGlobalSearchDue(permissions?: readonly string[] | null): boolean {
    const perms = permissions ?? [];
    return (
        perms.includes(Permissions.VIEW_DASHBOARD_JURIDICO) ||
        perms.includes(Permissions.VIEW_BROKER_DUE_DILIGENCE_2)
    );
}

export function canAccessGlobalSearchPos(permissions?: readonly string[] | null): boolean {
    return (permissions ?? []).includes(Permissions.VIEW_POS_AQUISICAO);
}

/** Seções que o FE pode oferecer nos chips (espelha gates BE, sem HostAllowedModule). */
export function enabledGlobalSearchSections(
    permissions?: readonly string[] | null,
): GlobalSearchSectionKey[] {
    const sections: GlobalSearchSectionKey[] = [];
    if (canAccessGlobalSearchPropostas(permissions)) sections.push('propostas');
    if (canAccessGlobalSearchDue(permissions)) sections.push('due');
    if (canAccessGlobalSearchPos(permissions)) sections.push('pos');
    return sections;
}

